mapper.update:
update embedding_index_write_lease
set expires_at = #{expiresAt}
where lease_token = #{leaseToken} and owner_id = #{ownerId}
  and expires_at > now(6)

mapper.select:
select count(*) from embedding_index_write_lease
where lease_token = #{leaseToken} and owner_id = #{ownerId}
  and expires_at > now(6)

select count(*) from physical_index_profile
where config_id = #{configId}
  and lifecycle_status in ('ACTIVE', 'BUILDING', 'ROLLBACK')
